<?php
require_once 'functions.php';require_role(['admin']);$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');$s=$pdo->prepare("SELECT COUNT(*) jumlah,COALESCE(SUM(total_bayar),0) pendapatan,COALESCE(SUM(diskon),0) diskon FROM tbl_transaksi WHERE status='selesai' AND tanggal BETWEEN ? AND ?");$s->execute([$from,$to]);$sum=$s->fetch();$s=$pdo->prepare("SELECT t.*,p.nama_pelanggan,u.nama AS kasir FROM tbl_transaksi t LEFT JOIN tbl_pelanggan p ON p.id_pelanggan=t.id_pelanggan LEFT JOIN users u ON u.id_user=t.id_user WHERE t.status='selesai' AND t.tanggal BETWEEN ? AND ? ORDER BY t.tanggal DESC");$s->execute([$from,$to]);$rows=$s->fetchAll();layout_header('Laporan');
?>
<div class="page-title"><div><span class="eyebrow">ANALISIS TOKO</span><h1>Laporan penjualan</h1><p>Ringkasan transaksi selesai berdasarkan periode.</p></div><button class="btn btn-outline" onclick="window.print()">Cetak Laporan</button></div><form class="panel search-form" method="get"><div><label>Dari tanggal</label><input type="date" name="from" value="<?=e($from)?>"></div><div><label>Sampai tanggal</label><input type="date" name="to" value="<?=e($to)?>"></div><button class="btn btn-primary">Tampilkan</button></form><div class="stats-grid" style="margin-top:18px"><div class="stat-card"><span>Transaksi selesai</span><strong><?=$sum['jumlah']?></strong></div><div class="stat-card accent"><span>Total pendapatan</span><strong><?=rupiah($sum['pendapatan'])?></strong></div><div class="stat-card"><span>Total diskon</span><strong><?=rupiah($sum['diskon'])?></strong></div></div><div class="section-head"><h2>Rincian transaksi</h2></div><div class="table-wrap"><table><thead><tr><th>Nomor</th><th>Tanggal</th><th>Pelanggan</th><th>Kasir</th><th>Total</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['nomor_transaksi'])?></td><td><?=e($r['tanggal'])?></td><td><?=e($r['nama_pelanggan']??'-')?></td><td><?=e($r['kasir']??'-')?></td><td><?=rupiah($r['total_bayar'])?></td></tr><?php endforeach;?></tbody></table></div>
<?php layout_footer(); ?>
